@dataclass(frozen=True)
class FamilySpec:
    family_id: str
    seed: int
    series_id: str
    split: Split = Split.DEV


DEV_FAMILIES = (
    FamilySpec("fam_01", 7, "CA_2_FOODS"),
    FamilySpec("fam_02", 11, "TX_1_HOUSEHOLD"),
)
FAMILY_ID = DEV_FAMILIES[0].family_id
SERIES_ID = DEV_FAMILIES[0].series_id


def heldout_spec(family_id: str, seed: int) -> FamilySpec:
    """A held-out family from its sealed seed; the seed also picks the series."""
    series = sorted(
        f"{store}_{category}" for store in STORES for category in CATEGORY_LEVEL
    )
    return FamilySpec(family_id, seed, series[seed % len(series)], Split.HELDOUT)


REVIEW_DAY = 196
PERIOD = DayRange(start_day=169, end_day=196)
WINDOW = DayRange(start_day=141, end_day=168)

MISSING_DAYS = (175, 176, 182, 189)
DUPLICATE_DAYS = (171, 178, 185)
DOUBLE_LOAD = 2.0  # the duplicate copy counts the units twice
SWAPPED_MODEL_NOISE = 2.0  # the window's other model sat close to the actuals
BIAS_FACTOR = 0.85
WEEKLY_SCHEDULE = (
    *((day, tuple(range(1, 8))) for day in (140, 147, 154, 161)),  # window: 1-7 ahead
    *((day, tuple(range(22, 29))) for day in (147, 154, 161, 168)),  # period: 22-28
)


def growing_noise(horizon: int) -> float:
    """Forecast noise that grows with the days ahead, as real forecast error does."""
    return 1.5 + 0.5 * horizon


